import pandas as pd


def _last_month_end_position(index):
    if index is None or len(index) == 0:
        return -1
    try:
        ym = index.year.to_numpy() * 12 + index.month.to_numpy()
    except Exception:
        return len(index) - 1
    cur = ym[-1]
    prev = np.where(ym < cur)[0]
    if prev.size > 0:
        return int(prev[-1])
    return len(index) - 1


def generate_weights(history, universe):
