    vol_window = min(126, n - 1)
    if vol_window < 20:
        w = _zero(universe)
        _CACHE[cache_key] = w
        return w.copy()

    vol = rets.iloc[-vol_window:].std(ddof=0)
    valid = last.notna() & (last > 0) & vol.notna() & (vol > 1e-8)

    if n >= 22:
        r21 = last / px.iloc[-22] - 1.0
    else:
