import numpy as np
import pandas as pd


def _get_field(history, candidates, universe):
    if isinstance(history, dict):
        for key in candidates:
            if key in history:
                obj = history[key]
                if isinstance(obj, pd.DataFrame):
                    try:
                        return obj.reindex(columns=universe)
                    except Exception:
                        return None
    return None


def generate_weights(history, universe):
    universe = pd.Index(universe)
    zeros = pd.Series(0.0, index=universe, dtype=float)
    if len(universe) == 0:
        return zeros

    adj = _get_field(history, ['adjusted_close'], universe)
    close = _get_field(history, ['close'], universe)
    if adj is None:
        adj = close
    elif close is not None:
        adj = adj.combine_first(close.reindex_like(adj))
    if adj is None or adj.shape[1] == 0:
        return zeros

    adj = adj.sort_index().tail(300)
    if len(adj) < 60:
        return zeros

    eligible = pd.Series(True, index=universe, dtype=bool)
    elig_df = _get_field(history, ['eligible'], universe)
    if elig_df is not None and len(elig_df) > 0:
        last = elig_df.sort_index().iloc[-1]
        last = last.reindex(universe).fillna(True)
        try:
            eligible = last.astype(bool)
        except Exception:
            eligible = pd.Series(True, index=universe, dtype=bool)

    skip = 5
    rets_win = None
    market = None
    if len(adj) >= 126:
        rec = adj.tail(130)
        rets = rec.pct_change()
        if len(rets) >= 126:
            rets_win = rets.iloc[-125:-5]
            market = rets_win.mean(axis=1, skipna=True)

    rows = []
    for t in universe:
        if not bool(eligible.get(t, True)):
            continue
        s = adj[t].dropna()
        if len(s) < 66:
            continue
        vals = s.values.astype(float)
        vals = vals[np.isfinite(vals)]
        if len(vals) < 66 or vals[-1] <= 0:
            continue

        def ret_vol(lookback):
            end = len(vals) - skip
            if end <= lookback:
                return np.nan, np.nan
            start = end - (lookback + 1)
            if start < 0:
                return np.nan, np.nan
            w = vals[start:end]
            if len(w) < lookback + 1 or w[0] <= 0 or w[-1] <= 0:
                return np.nan, np.nan
            ret = w[-1] / w[0] - 1.0
            lr = np.diff(np.log(w))
            vol = float(np.std(lr, ddof=1)) if len(lr) > 1 else np.nan
            return ret, vol

        r120, v120 = ret_vol(120)
        r60, v60 = ret_vol(60)
        if not np.isfinite(r120) or not np.isfinite(v120) or v120 <= 0:
            continue
        if not np.isfinite(r60) or not np.isfinite(v60) or v60 <= 0:
            r60, v60 = r120, v120

        end = len(vals) - skip
        if end < 60:
            continue
        start = max(0, end - 252)
        high = np.nanmax(vals[start:end])
        if not np.isfinite(high) or high <= 0:
            continue
        prox = vals[end - 1] / high
        if not np.isfinite(prox):
            continue

        resid = np.nan
        if rets_win is not None and t in rets_win.columns:
            r = rets_win[t].values.astype(float)
            m = market.values.astype(float)
            mask = np.isfinite(r) & np.isfinite(m)
            if mask.sum() >= 40:
                rm = r[mask]
                mm = m[mask]
                var = np.var(mm, ddof=1)
                if var > 1e-12:
                    beta = np.cov(rm, mm, ddof=1)[0, 1] / var
                    resid = float(np.sum(rm - beta * mm))

        rows.append({'ticker': t, 'r120': r120, 'r60': r60,
                     'v120': v120, 'v60': v60, 'prox': prox, 'resid': resid})

    if len(rows) < 4:
        return zeros

    df = pd.DataFrame(rows).set_index('ticker')
    df = df.replace([np.inf, -np.inf], np.nan)
    df = df.dropna(subset=['r120', 'v120', 'prox'])
    if len(df) < 4:
        return zeros

    eps = 1e-12
    mom120 = df['r120'] / (df['v120'] * np.sqrt(120.0) + eps)
    mom60 = df['r60'].fillna(df['r120']) / (df['v60'].fillna(df['v120']) * np.sqrt(60.0) + eps)
    resid_mom = df['resid'].fillna(0.0) / (df['v120'] * np.sqrt(120.0) + eps)

    def rp(s, ascending=True):
        return pd.Series(s, dtype=float).rank(pct=True, ascending=ascending).fillna(0.5)

    score = (0.40 * rp(mom120) +
             0.20 * rp(mom60) +
             0.15 * rp(resid_mom) +
             0.15 * rp(df['prox']) -
             0.10 * rp(df['v120'], ascending=True))
    score = score.replace([np.inf, -np.inf], np.nan).dropna()
    if len(score) < 4:
        return zeros

    n = len(score)
    k = min(25, n // 2)
    if k < 2:
        return zeros

    longs = score.nlargest(k).index
    shorts = score.nsmallest(k).index
    w = min(0.02, 1.0 / (2.0 * k))

    weights = zeros.copy()
    weights.loc[longs] = w
    weights.loc[shorts] = -w
    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0)
    return weights

import numpy as np
import pandas as pd

_STATE = {'last_date': None, 'last_reb': None, 'weights': None}
_MAX_NAMES = 12
_SIDE_GROSS = 0.20
_CAP = 0.02
_REBAL_DAYS = 7

def _map_weights(prev, univ):
    out = pd.Series(0.0, index=univ, dtype=float)
    if prev is None:
        return out
    for t, w in prev.items():
        if t in out.index:
            out.loc[t] = float(w)
    return out

def _reset_if_needed(dt):
    if _STATE['last_date'] is not None and dt < _STATE['last_date']:
        _STATE['last_date'] = None
        _STATE['last_reb'] = None
        _STATE['weights'] = None

def _rank_centered(s):
    return s.rank(pct=True) - 0.5

def _compute_scores(history, cols):
    adj_df = history.get('adjusted_close')
    if adj_df is None:
        adj_df = history.get('close')
    if adj_df is None or len(cols) == 0:
        return None
    use_cols = [c for c in cols if c in adj_df.columns]
    if len(use_cols) == 0:
        return None
    adj = adj_df.loc[:, use_cols].tail(95).apply(pd.to_numeric, errors='coerce')
    if adj.shape[0] < 6:
        return None
    last = adj.iloc[-1]
    ret = adj.pct_change()
    r5 = last / adj.iloc[-6] - 1.0
    if adj.shape[0] >= 22:
        r21 = last / adj.iloc[-22] - 1.0
    else:
        r21 = pd.Series(np.nan, index=use_cols)
    vol = ret.tail(20).std(ddof=0)
    pos = vol[vol > 0]
    med = pos.median() if len(pos) > 0 else np.nan
    if (not np.isfinite(med)) or med <= 0:
        vol = pd.Series(1.0, index=use_cols)
    else:
        vol = vol.fillna(med)
        vol = vol.where(vol > 0, med)
    r5v = r5 / (vol * np.sqrt(5.0))
    r21v = r21 / (vol * np.sqrt(21.0))
    if r21v.notna().sum() >= max(5, len(use_cols) // 3):
        score = -0.65 * _rank_centered(r5v) - 0.35 * _rank_centered(r21v)
    else:
        score = -_rank_centered(r5v)
    valid = last.notna() & r5.notna() & score.replace([np.inf, -np.inf], np.nan).notna()
    elig_df = history.get('eligible')
    if elig_df is not None:
        ec = [c for c in use_cols if c in elig_df.columns]
        if len(ec) > 0:
            e = elig_df.loc[:, ec].tail(1).iloc[-1].reindex(use_cols).fillna(False).astype(bool)
            valid = valid & e
    vol_df = history.get('volume')
    if vol_df is not None:
        vc = [c for c in use_cols if c in vol_df.columns]
        if len(vc) > 0:
            vv = vol_df.loc[:, vc].tail(20).apply(pd.to_numeric, errors='coerce')
            pp = adj.tail(20).reindex(columns=vc)
            dollar = (vv * pp).median().reindex(use_cols)
            valid = valid & (dollar.fillna(0.0) > 1000000.0)
    score = score[valid].dropna()
    score = score.replace([np.inf, -np.inf], np.nan).dropna()
    return score

def _select(score, prev_weights):
    n_total = len(score)
    if n_total < 2:
        return [], [], 0.0
    N = min(_MAX_NAMES, n_total // 2)
    if N < 1:
        return [], [], 0.0
    buffer = 2 * N if n_total >= 4 * N else N
    ordered_long = score.sort_values(ascending=False).index.tolist()
    ordered_short = score.sort_values(ascending=True).index.tolist()
    prev_long = set()
    prev_short = set()
    if prev_weights is not None:
        prev_long = set(prev_weights[prev_weights > 0].index)
        prev_short = set(prev_weights[prev_weights < 0].index)
    keep_long = [t for t in ordered_long[:buffer] if t in prev_long][:N]
    longs = keep_long[:]
    long_set = set(longs)
    for t in ordered_long:
        if len(longs) >= N:
            break
        if t not in long_set:
            longs.append(t)
            long_set.add(t)
    keep_short = [t for t in ordered_short[:buffer] if (t in prev_short) and (t not in long_set)][:N]
    shorts = keep_short[:]
    short_set = set(shorts)
    for t in ordered_short:
        if len(shorts) >= N:
            break
        if (t not in short_set) and (t not in long_set):
            shorts.append(t)
            short_set.add(t)
    M = min(len(longs), len(shorts), N)
    if M < 1:
        return [], [], 0.0
    longs = longs[:M]
    shorts = shorts[:M]
    base = min(_CAP, _SIDE_GROSS / float(M))
    return longs, shorts, base

def generate_weights(history, universe):
    univ = pd.Index(universe)
    zero = pd.Series(0.0, index=univ, dtype=float)
    if len(univ) == 0:
        return zero
    ref = None
    for k in ('adjusted_close', 'close', 'open'):
        df = history.get(k)
        if df is not None and len(df.index) > 0:
            ref = df
            break
    if ref is None:
        return zero
    dt = ref.index[-1]
    _reset_if_needed(dt)
    if _STATE['last_date'] is not None and dt == _STATE['last_date'] and _STATE['weights'] is not None:
        return _map_weights(_STATE['weights'], univ)
    due = _STATE['last_reb'] is None
    if not due:
        due = (dt - _STATE['last_reb']).days >= _REBAL_DAYS
    if (not due) and (_STATE['weights'] is not None):
        _STATE['last_date'] = dt
        return _map_weights(_STATE['weights'], univ)
    cols = list(univ)
    score = _compute_scores(history, cols)
    if score is None or len(score) < 2:
        w = zero.copy()
        _STATE['weights'] = w
        _STATE['last_reb'] = dt
        _STATE['last_date'] = dt
        return w
    longs, shorts, base = _select(score, _STATE['weights'])
    w = pd.Series(0.0, index=univ, dtype=float)
    if len(longs) > 0:
        for t in longs:
            if t in w.index:
                w.loc[t] = base
        for t in shorts:
            if t in w.index:
                w.loc[t] = -base
    w = w.clip(-_CAP, _CAP)
    net = float(w.sum())
    if abs(net) > 1e-12:
        nz = w[w != 0.0]
        if len(nz) > 0:
            w.loc[nz.index] -= net / float(len(nz))
    w = w.clip(-_CAP, _CAP)
    if abs(float(w.sum())) > 0.01:
        w = zero.copy()
    gross = float(w.abs().sum())
    if gross > 1.0:
        w = w / gross
    _STATE['weights'] = w.copy()
    _STATE['last_reb'] = dt
    _STATE['last_date'] = dt
    return w

import numpy as np
import pandas as pd

_CACHE = {}


def _zscore(s):
    s = s.replace([np.inf, -np.inf], np.nan)
    m = s.mean(skipna=True)
    sd = s.std(skipna=True)
    if not np.isfinite(sd) or sd <= 0:
        return pd.Series(0.0, index=s.index)
    return (s - m) / sd


def generate_weights(history, universe):
    u = list(universe)
    zero = pd.Series(0.0, index=u, dtype=float)
    try:
        adj = history["adjusted_close"]
    except Exception:
        return zero
    if not isinstance(adj, pd.DataFrame) or adj.shape[0] < 65:
        return zero

    idx = adj.index
    cut = len(idx) - 1
    if hasattr(idx, "year"):
        try:
            months = np.asarray(idx.year, dtype=np.int64) * 12 + np.asarray(idx.month, dtype=np.int64)
        except Exception:
            months = None
        if months is not None and len(months) > 1:
            ch = np.where(months[1:] != months[:-1])[0]
            if len(ch) > 0:
                cut = int(ch[-1])
            try:
                last_ts = idx[-1]
                nxt = last_ts + pd.tseries.offsets.BDay(1)
                if nxt.month != last_ts.month:
                    cut = len(idx) - 1
            except Exception:
                pass

    if cut < 60:
        return zero

    cut_date = idx[cut]
    key = (cut_date, len(u), u[0] if u else "", u[-1] if u else "")
    if key in _CACHE:
        return _CACHE[key].reindex(u).fillna(0.0).astype(float)

    adj_sub = adj.iloc[: cut + 1]
    n = len(adj_sub)
    cols = [c for c in u if c in adj_sub.columns]
    if len(cols) < 30:
        return zero
    px = adj_sub[cols].astype(float)

    try:
        el = history["eligible"]
        if isinstance(el, pd.DataFrame):
            el_a = el.reindex(adj_sub.index)
            el_last = el_a.iloc[-1].reindex(cols) if len(el_a) > 0 else pd.Series(True, index=cols)
        else:
            el_last = pd.Series(True, index=cols)
    except Exception:
        el_last = pd.Series(True, index=cols)
    el_last = el_last.fillna(False).astype(bool)

    try:
        vh = history["volume"]
        if isinstance(vh, pd.DataFrame):
            vh_a = vh.reindex(adj_sub.index)
            tail_v = vh_a.iloc[-61:][cols] if len(vh_a) >= 1 else None
            med_vol = tail_v.median() if tail_v is not None else pd.Series(np.inf, index=cols)
        else:
            med_vol = pd.Series(np.inf, index=cols)
    except Exception:
        med_vol = pd.Series(np.inf, index=cols)
    if not isinstance(med_vol, pd.Series):
        med_vol = pd.Series(np.inf, index=cols)

    last = px.iloc[-1]
    valid = el_last & last.notna() & (last > 1.0) & (med_vol.reindex(cols).fillna(0) > 50000)
    if int(valid.sum()) < 20:
        return zero

    tail_px = px.iloc[-61:]
    rets = tail_px.pct_change()
    vol = rets.std()
    vol = vol.replace(0, np.nan).fillna(1e-4).clip(lower=1e-5)

    skip = int(min(21, max(1, n // 12)))
    look = int(min(252, n - skip - 5))
    if look < 20:
        return zero
    end_i = n - 1 - skip
    start_i = max(0, end_i - look)
    mom = px.iloc[end_i] / px.iloc[start_i] - 1.0
    mom = mom.replace([np.inf, -np.inf], np.nan)

    rev_look = int(min(5, n - 1))
    rev = px.iloc[-1] / px.iloc[-1 - rev_look] - 1.0
    rev = rev.replace([np.inf, -np.inf], np.nan)

    mom_ra = mom / vol
    rev_ra = -rev / vol
    score = _zscore(mom_ra) + 0.5 * _zscore(rev_ra)
    score = score.where(valid).replace([np.inf, -np.inf], np.nan).dropna()
    if len(score) < 20:
        return zero

    n_side = min(50, len(score) // 2)
    if n_side < 5:
        return zero
    w_side = 0.5 / n_side
    if w_side > 0.02:
        w_side = 0.02
        n_side = min(n_side, 25)

    ranked = score.sort_values(kind="mergesort")
    shorts = ranked.index[:n_side]
    longs = ranked.index[-n_side:]

    w = zero.copy()
    w.loc[longs] = w_side
    w.loc[shorts] = -w_side
    _CACHE[key] = w
    return w

import numpy as np
import pandas as pd


def _zrank(s):
    s = s.replace([np.inf, -np.inf], np.nan)
    r = s.rank(pct=True)
    return (2.0 * r - 1.0).fillna(0.0)


def generate_weights(history, universe):
    u = list(universe)
    if len(u) == 0:
        return pd.Series(dtype=float)
    zeros = pd.Series(0.0, index=u, dtype=float)
    if history is None:
        return zeros

    ac = history.get('adjusted_close')
    if ac is None:
        ac = history.get('close')
    if ac is None:
        return zeros
    try:
        if ac.empty:
            return zeros
    except Exception:
        return zeros

    cols = [t for t in u if t in ac.columns]
    if len(cols) < 10:
        return zeros

    px = ac.loc[:, cols].astype(float)
    if len(px) < 40:
        return zeros

    idx = px.index
    t = idx[-1]

    # Rebalance weekly using Monday close; hold through the week.
    if t.weekday() == 0:
        sig = t
    else:
        sig = None
        for j in range(len(idx) - 1, max(-1, len(idx) - 15), -1):
            if idx[j].weekday() == 0:
                sig = idx[j]
                break
        if sig is None:
            sig = idx[-1]

    sub = px.loc[:sig]
    n = len(sub)
    if n < 30:
        return zeros

    elig = pd.Series(True, index=cols)
    e = history.get('eligible')
    if e is not None:
        try:
            ee = e.reindex(columns=cols).loc[:sig]
            if len(ee) > 0:
                elig = ee.iloc[-1].fillna(False).astype(bool)
        except Exception:
            pass

    def at(k):
        pos = n - 1 - k
        if pos < 0:
            return pd.Series(np.nan, index=cols)
        return sub.iloc[pos]

    p0 = at(0)
    p5 = at(5)
    p10 = at(10)
    p21 = at(21)
    p63 = at(63)

    rets = sub.pct_change()
    vol = rets.iloc[-61:].std()

    dv = pd.Series(np.nan, index=cols)
    v = history.get('volume')
    c = history.get('close')
    if v is not None and c is not None:
        try:
            vv = v.reindex(index=sub.index, columns=cols).iloc[-20:]
            cc = c.reindex(index=sub.index, columns=cols).iloc[-20:]
            dv = (vv * cc).median(axis=0, skipna=True)
        except Exception:
            pass

    with np.errstate(divide='ignore', invalid='ignore'):
        r5 = (p0 / p5 - 1.0).replace([np.inf, -np.inf], np.nan)
        r10 = (p0 / p10 - 1.0).replace([np.inf, -np.inf], np.nan)
        r21 = (p0 / p21 - 1.0).replace([np.inf, -np.inf], np.nan)
        r63 = (p0 / p63 - 1.0).replace([np.inf, -np.inf], np.nan)

    s_rev = _zrank(-r5) + 0.7 * _zrank(-r21) + 0.3 * _zrank(-r10)
    s_vol = _zrank(vol)
    s_trend = _zrank(r63)
    score = s_rev - 0.4 * s_vol + 0.1 * s_trend

    valid = elig & p0.notna() & (p0 > 1.0) & p5.notna() & p21.notna() & vol.notna() & (vol > 0)

    if dv.notna().any():
        posdv = dv[dv > 0]
        if len(posdv) > 5:
            thr = posdv.quantile(0.20)
            valid = valid & dv.notna() & (dv >= thr)
        else:
            valid = valid & dv.notna()
    valid = valid.fillna(False)

    if int(valid.sum()) < 12:
        valid = elig & p0.notna() & (p0 > 1.0) & p5.notna()
        valid = valid.fillna(False)
        if int(valid.sum()) < 8:
            return zeros
        score = _zrank(-r5) - 0.2 * _zrank(vol)

    score = score.where(valid)
    score = score.replace([np.inf, -np.inf], np.nan).dropna()
    if len(score) < 8:
        return zeros

    n_side = min(25, len(score) // 2)
    if n_side < 4:
        return zeros

    w_side = min(0.02, 0.5 / float(n_side))
    ranked = score.sort_values(kind='mergesort')
    shorts = ranked.index[:n_side]
    longs = ranked.index[-n_side:]

    w = zeros.copy()
    w.loc[longs] = w_side
    w.loc[shorts] = -w_side
    return w

import numpy as np
import pandas as pd

_CACHE = {}


def _zrank(s, valid=None):
    s = s.astype(float).replace([np.inf, -np.inf], np.nan)
    if valid is not None:
        s = s.where(valid)
    r = s.rank(pct=True)
    return (2.0 * r - 1.0).fillna(0.0)


def generate_weights(history, universe):
    u = list(universe)
    if len(u) == 0:
        return pd.Series(dtype=float)
    zero = pd.Series(0.0, index=u, dtype=float)
    if history is None:
        return zero
    ac = history.get('adjusted_close')
    if ac is None:
        ac = history.get('close')
    if ac is None:
        return zero
    try:
        if ac.empty:
            return zero
    except Exception:
        return zero
    cols = [t for t in u if t in ac.columns]
    if len(cols) < 10:
        return zero
    px = ac.loc[:, cols].astype(float)
    if not px.index.is_monotonic_increasing:
        px = px.sort_index()
    if len(px) > 400:
        px = px.iloc[-400:]
    px = px.dropna(how='all')
    if len(px) < 40:
        return zero
    idx = px.index
    t = idx[-1]
    try:
        nb = t + pd.offsets.BDay(1)
        at_me = (nb.year != t.year) or (nb.month != t.month)
    except Exception:
        at_me = False
    if at_me:
        sig = t
    else:
        try:
            months = np.asarray(idx.year, dtype=np.int64) * 12 + np.asarray(idx.month, dtype=np.int64)
            cur = int(t.year) * 12 + int(t.month)
            prior = idx[months < cur]
        except Exception:
            prior = idx[:-1]
        if len(prior) == 0:
            return zero
        sig = prior[-1]
    key = (sig, tuple(u))
    if key in _CACHE:
        return _CACHE[key].reindex(u).fillna(0.0).astype(float)
    sub = px.loc[:sig]
    n = len(sub)
    if n < 274:
        return zero
    p0 = sub.iloc[-1]
    skip = 21
    long = 252
    end_i = n - 1 - skip
    start_i = end_i - long
    if start_i < 0:
        return zero
    p_end = sub.iloc[end_i]
    p_start = sub.iloc[start_i]
    mom12 = (p_end / p_start - 1.0).replace([np.inf, -np.inf], np.nan)
    start6 = end_i - 126
    if start6 >= 0:
        mom6 = (p_end / sub.iloc[start6] - 1.0).replace([np.inf, -np.inf], np.nan)
    else:
        mom6 = pd.Series(np.nan, index=cols)
    rets = sub.pct_change()
    if len(rets) >= 126:
        vol = rets.iloc[-126:].std()
    else:
        vol = rets.std()
    dvol = pd.Series(np.nan, index=cols)
    v = history.get('volume')
    c = history.get('close')
    if v is not None and c is not None:
        try:
            vv = v.reindex(columns=cols)
            cc = c.reindex(columns=cols)
            vv = vv.reindex(sub.index).tail(20)
            cc = cc.reindex(sub.index).tail(20)
            dvol = (vv * cc).median(axis=0, skipna=True)
        except Exception:
            pass
    elig = pd.Series(True, index=cols)
    e = history.get('eligible')
    if e is not None:
        try:
            ee = e.reindex(columns=cols)
            ee = ee.reindex(sub.index)
            if len(ee) > 0:
                elig = ee.iloc[-1].fillna(False).astype(bool)
        except Exception:
            pass
    valid = elig.reindex(cols).fillna(False).astype(bool)
    valid = valid & p0.notna() & (p0 > 1.0) & mom12.notna() & mom6.notna() & vol.notna() & (vol > 0.0)
    if dvol.notna().any():
        pos = dvol[dvol > 0.0]
        if len(pos) >= 10:
            thr = pos.quantile(0.20)
            valid = valid & dvol.notna() & (dvol >= thr)
        else:
            valid = valid & dvol.notna()
    valid = valid.fillna(False)
    if int(valid.sum()) < 20:
        valid = elig.reindex(cols).fillna(False).astype(bool) & p0.notna() & (p0 > 1.0) & mom12.notna()
        valid = valid.fillna(False)
        if int(valid.sum()) < 10:
            return zero
        score = _zrank(mom12, valid)
    else:
        z12 = _zrank(mom12, valid)
        z6 = _zrank(mom6, valid)
        zv = _zrank(vol, valid)
        score = 0.7 * z12 + 0.3 * z6 - 0.2 * zv
    score = score.replace([np.inf, -np.inf], np.nan)
    score[~valid] = np.nan
    score = score.dropna()
    if len(score) < 10:
        return zero
    n_side = min(50, len(score) // 2)
    if n_side < 5:
        return zero
    w_side = min(0.02, 0.5 / float(n_side))
    ranked = score.sort_values(kind='mergesort')
    shorts = ranked.index[:n_side]
    longs = ranked.index[-n_side:]
    w = zero.copy()
    w.loc[longs] = w_side
    w.loc[shorts] = -w_side
    out = w.reindex(u).fillna(0.0).astype(float)
    _CACHE[key] = out
    return out

import numpy as np
import pandas as pd

def _get_df(history, key):
    df = history.get(key)
    if df is None:
        return None
    return df

def _rebalance_date(index):
    if len(index) == 0:
        return None
    cur = index[-1]
    try:
        mask = (index.weekday == 4) & (index <= cur)
        if mask.any():
            return index[mask][-1]
    except Exception:
        pass
    return cur

def generate_weights(history, universe):
    idx = pd.Index(universe)
    w = pd.Series(0.0, index=idx, dtype=float)
    adj = _get_df(history, 'adjusted_close')
    if adj is None or adj.empty:
        adj = _get_df(history, 'close')
    if adj is None or adj.empty:
        return w
    adj = adj.reindex(columns=idx)
    if adj.empty:
        return w
    rd = _rebalance_date(adj.index)
    if rd is None:
        return w

    def sl(key):
        df = _get_df(history, key)
        if df is None:
            return None
        try:
            return df.loc[:rd].reindex(columns=idx)
        except Exception:
            return df.reindex(columns=idx)

    adj = sl('adjusted_close')
    if adj is None or adj.empty:
        adj = sl('close')
    if adj is None or adj.empty:
        return w
    close_df = sl('close')
    if close_df is None:
        close_df = adj
    vol_df = sl('volume')
    elig_df = sl('eligible')
    last_e = None
    if elig_df is not None and len(elig_df) > 0:
        last_e = elig_df.iloc[-1]

    rows = []
    for t in idx:
        if t not in adj.columns:
            continue
        s = adj[t].dropna()
        n = len(s)
        if n < 80:
            continue
        p = float(s.iloc[-1])
        if not np.isfinite(p) or p <= 1.0:
            continue
        if last_e is not None:
            ev = last_e.get(t, False)
            try:
                if pd.isna(ev) or not bool(ev):
                    continue
            except Exception:
                if not bool(ev):
                    continue
        if vol_df is not None and close_df is not None:
            v = vol_df[t].dropna()
            c = close_df[t].dropna()
            if len(v) >= 5 and len(c) >= 5:
                dv = (c * v).dropna()
                if len(dv) >= 5:
                    mdv = float(dv.iloc[-20:].median())
                    if np.isfinite(mdv) and mdv < 1e6:
                        continue
        ret = s.pct_change().dropna()
        if len(ret) < 30:
            continue
        vol = float(ret.iloc[-60:].std())
        if not np.isfinite(vol) or vol <= 1e-12:
            vol = float(ret.std())
        if not np.isfinite(vol) or vol <= 1e-12:
            continue
        if n >= 253:
            mom = float(s.iloc[-22] / s.iloc[-253] - 1.0)
        elif n > 22:
            mom = float(s.iloc[-22] / s.iloc[0] - 1.0)
        else:
            mom = float(s.iloc[-1] / s.iloc[0] - 1.0)
        if n >= 22:
            rev = float(-(s.iloc[-1] / s.iloc[-22] - 1.0))
        else:
            rev = 0.0
        if not np.isfinite(mom):
            mom = 0.0
        if not np.isfinite(rev):
            rev = 0.0
        rows.append((t, mom, rev, vol))

    if len(rows) < 10:
        return w
    tickers = [r[0] for r in rows]
    mom = np.array([r[1] for r in rows], dtype=float)
    rev = np.array([r[2] for r in rows], dtype=float)
    vol = np.array([r[3] for r in rows], dtype=float)

    def rz(x):
        x = np.asarray(x, dtype=float)
        x = np.nan_to_num(x, nan=0.0, posinf=0.0, neginf=0.0)
        lo = np.nanpercentile(x, 5)
        hi = np.nanpercentile(x, 95)
        x = np.clip(x, lo, hi)
        med = np.nanmedian(x)
        mad = np.nanmedian(np.abs(x - med))
        if not np.isfinite(mad) or mad <= 1e-12:
            sd = np.nanstd(x)
            if not np.isfinite(sd) or sd <= 1e-12:
                return np.zeros_like(x)
            return (x - med) / sd
        return (x - med) / (1.4826 * mad)

    score = 1.0 * rz(mom) + 0.5 * rz(rev) - 0.4 * rz(np.log(np.maximum(vol, 1e-8)))
    score = np.nan_to_num(score, nan=0.0, posinf=0.0, neginf=0.0)
    order = np.argsort(score)
    m = len(order)
    k = min(25, m // 2)
    if k < 1:
        return w
    short_i = order[:k]
    long_i = order[-k:]
    wt = min(0.02, 1.0 / (2.0 * k))
    for i in long_i:
        w.loc[tickers[i]] = wt
    for i in short_i:
        w.loc[tickers[i]] = -wt
    return w

import numpy as np
import pandas as pd


def _zscore(s):
    s = s.replace([np.inf, -np.inf], np.nan)
    mu = s.mean()
    sd = s.std(ddof=0)
    if not np.isfinite(sd) or sd < 1e-12:
        return pd.Series(0.0, index=s.index)
    z = (s - mu) / sd
    return z.clip(-3.0, 3.0)


def generate_weights(history, universe):
    u = pd.Index(universe)
    if len(u) == 0:
        return pd.Series(dtype=float, index=u)

    adj = history.get('adjusted_close')
    if adj is None or not isinstance(adj, pd.DataFrame):
        adj = history.get('close')
    if adj is None or not isinstance(adj, pd.DataFrame):
        return pd.Series(0.0, index=u)

    adj = adj.reindex(columns=u)
    if len(adj) < 130:
        return pd.Series(0.0, index=u)

    idx = adj.index
    last_pos = len(idx) - 1
    mondays = np.where(idx.dayofweek == 0)[0]
    if len(mondays) > 0:
        base_pos = int(mondays[-1])
        if base_pos < 129:
            base_pos = last_pos
    else:
        base_pos = last_pos

    start = max(0, base_pos - 259)
    adj_w = adj.iloc[start:base_pos + 1]
    if len(adj_w) < 130:
        base_pos = last_pos
        start = max(0, base_pos - 259)
        adj_w = adj.iloc[start:base_pos + 1]
    if len(adj_w) < 130:
        return pd.Series(0.0, index=u)

    valid = pd.Series(True, index=u)
    last_adj = adj_w.iloc[-1]
    valid &= np.isfinite(last_adj.values) & (last_adj.values > 0)
    valid &= (adj_w.notna().sum().values >= min(130, len(adj_w)))

    elig = history.get('eligible')
    if elig is not None and isinstance(elig, pd.DataFrame):
        elig2 = elig.reindex(columns=u)
        if len(elig2) > 0:
            if base_pos < len(elig2):
                e = elig2.iloc[base_pos]
            else:
                e = elig2.iloc[-1]
            valid &= e.fillna(False).astype(bool).values

    volume = history.get('volume')
    if volume is not None and isinstance(volume, pd.DataFrame):
        vol2 = volume.reindex(columns=u).iloc[start:base_pos + 1]
        vtail = vol2.iloc[-20:]
        close = history.get('close')
        if close is not None and isinstance(close, pd.DataFrame):
            px = close.reindex(columns=u).iloc[start:base_pos + 1].iloc[-20:]
        else:
            px = adj_w.iloc[-20:]
        dollar = (vtail * px).median()
        valid &= np.isfinite(dollar.values) & (dollar.values > 1e6)

    arr_last = adj_w.iloc[-1]
    r5 = arr_last / adj_w.iloc[-6] - 1.0

    if len(adj_w) >= 127:
        mom = adj_w.iloc[-22] / adj_w.iloc[-127] - 1.0
    else:
        mom = pd.Series(np.nan, index=u)

    rets = adj_w.pct_change()
    vol = rets.iloc[-126:].std(ddof=0)
    vol = vol.replace(0.0, np.nan)

    rev_score = -r5 / (vol * np.sqrt(5.0))
    mom_score = mom / (vol * np.sqrt(105.0))
    rev_score = rev_score.replace([np.inf, -np.inf], np.nan)
    mom_score = mom_score.replace([np.inf, -np.inf], np.nan)

    signal = 0.7 * _zscore(mom_score) + 0.3 * _zscore(rev_score)
    signal = signal.replace([np.inf, -np.inf], np.nan)

    cand_mask = valid.values & np.isfinite(signal.values)
    cand = list(u[cand_mask])
    m = len(cand)
    if m < 10:
        return pd.Series(0.0, index=u)

    n = min(30, m // 2)
    if n < 1:
        return pd.Series(0.0, index=u)

    ordered = signal.loc[cand].sort_values(ascending=False, kind='mergesort')
    longs = ordered.index[:n]
    shorts = ordered.index[-n:]

    side_weight = 0.5 / n
    w = min(side_weight, 0.02)

    weights = pd.Series(0.0, index=u)
    weights.loc[longs] = w
    weights.loc[shorts] = -w
    return weights.astype(float)

import numpy as np
import pandas as pd

def _zeros(universe):
    return pd.Series(0.0, index=universe, dtype=float)

def generate_weights(history, universe):
    tickers = list(universe)
    if len(tickers) == 0:
        return pd.Series(dtype=float)

    n = len(tickers)
    ret5 = np.full(n, np.nan, dtype=float)
    vol20 = np.full(n, np.nan, dtype=float)
    liq = np.full(n, np.nan, dtype=float)

    for i, t in enumerate(tickers):
        df = history.get(t)
        if df is None:
            continue
        try:
            m = len(df)
        except Exception:
            continue
        if m == 0:
            continue

        sub = df.iloc[-min(m, 30):]
        if 'adjusted_close' not in sub.columns:
            continue

        ac = sub['adjusted_close'].to_numpy(dtype=float)
        if len(ac) < 8:
            continue
        if (not np.isfinite(ac[-1])) or ac[-1] <= 0.0:
            continue

        if 'eligible' in sub.columns:
            e = sub['eligible'].iloc[-1]
            if not pd.notna(e) or not bool(e):
                continue

        if len(ac) >= 6:
            p0 = ac[-6]
            if np.isfinite(p0) and p0 > 0.0:
                ret5[i] = ac[-1] / p0 - 1.0

        if len(ac) >= 21:
            vals = ac[-21:]
            ok = np.isfinite(vals) & (vals > 0.0)
            if ok.sum() >= 15:
                logs = np.log(vals)
                lr = np.diff(logs)
                lr = lr[np.isfinite(lr)]
                if len(lr) >= 10:
                    vol20[i] = float(np.std(lr, ddof=1)) * np.sqrt(252.0)

        if 'volume' in sub.columns and len(ac) >= 5:
            v = sub['volume'].to_numpy(dtype=float)[-20:]
            p = ac[-20:]
            k = min(len(v), len(p))
            if k >= 5:
                v = v[-k:]
                p = p[-k:]
                good = np.isfinite(v) & np.isfinite(p) & (v >= 0.0) & (p > 0.0)
                if good.sum() >= 5:
                    dv = v[good] * p[good]
                    liq[i] = float(np.median(dv))

    valid = (
        np.isfinite(ret5)
        & np.isfinite(vol20)
        & (vol20 > 0.0)
        & np.isfinite(liq)
        & (liq > 0.0)
    )
    if valid.sum() < 4:
        return _zeros(universe)

    liq_valid = liq[valid]
    liq_threshold = float(np.median(liq_valid))
    liquid = valid & (liq >= liq_threshold)
    if liquid.sum() < 4:
        liquid = valid

    score = np.full(n, np.nan, dtype=float)
    r = ret5[liquid].copy()
    if len(r) >= 4:
        lo = float(np.percentile(r, 2.5))
        hi = float(np.percentile(r, 97.5))
        r = np.clip(r, lo, hi)
    score_liquid = -r / np.maximum(vol20[liquid], 0.10)
    score[liquid] = score_liquid

    candidates = np.where(np.isfinite(score))[0]
    if len(candidates) < 2:
        return _zeros(universe)

    order = candidates[np.argsort(-score[candidates], kind='mergesort')]
    side = min(25, len(order) // 2)
    if side < 1:
        return _zeros(universe)

    long_idx = order[:side]
    short_idx = order[-side:]
    per = min(0.019999, 0.5 / float(side))

    w = pd.Series(0.0, index=universe, dtype=float)
    for idx in long_idx:
        w.iloc[int(idx)] = per
    for idx in short_idx:
        w.iloc[int(idx)] = -per

    return w

import numpy as np
import pandas as pd


def _rank_pct(s):
    return s.rank(method='average', pct=True)


def generate_weights(history, universe):
    u = pd.Index(universe)
    zero = pd.Series(0.0, index=u, dtype=float)
    if len(u) == 0:
        return zero

    ac = history.get('adjusted_close')
    if not isinstance(ac, pd.DataFrame) or ac.empty:
        ac = history.get('close')
    if not isinstance(ac, pd.DataFrame) or ac.empty:
        return zero

    cols = [c for c in u if c in ac.columns]
    if len(cols) < 10:
        return zero

    ac = ac.reindex(columns=cols)
    nrows = len(ac)
    if nrows < 130:
        return zero

    last_pos = nrows - 1
    reb_pos = last_pos - (last_pos % 21)
    if reb_pos < 129:
        reb_pos = last_pos

    start = max(0, reb_pos - 260)
    p = ac.iloc[start:reb_pos + 1].copy()
    if len(p) < 70:
        return zero
    p = p.ffill()

    last = p.iloc[-1]
    valid = last.notna() & (last > 0.5)

    raw = ac.iloc[start:reb_pos + 1]
    need = min(60, len(raw))
    valid = valid & (raw.notna().sum() >= need)

    vol_df = history.get('volume')
    if isinstance(vol_df, pd.DataFrame):
        v = vol_df.reindex(index=ac.index, columns=cols).iloc[start:reb_pos + 1].ffill()
        close_df = history.get('close')
        if isinstance(close_df, pd.DataFrame):
            px = close_df.reindex(index=ac.index, columns=cols).iloc[start:reb_pos + 1].ffill()
        else:
            px = p
        if len(v) >= 20:
            dv = (v.iloc[-20:] * px.iloc[-20:]).median()
            valid = valid & dv.notna() & (dv > 1e6)

    elig_df = history.get('eligible')
    if isinstance(elig_df, pd.DataFrame):
        e = elig_df.reindex(index=ac.index, columns=cols).iloc[start:reb_pos + 1].ffill().iloc[-1]
        valid = valid & e.fillna(False).astype(bool)

    p = p.loc[:, valid]
    if p.shape[1] < 10:
        return zero

    rets = p.pct_change()
    vol = rets.iloc[-60:].std(ddof=0)
    maxret = rets.iloc[-21:].max()

    if len(p) >= 22:
        rev = -(p.iloc[-1] / p.iloc[-22] - 1.0)
    else:
        rev = pd.Series(np.nan, index=p.columns)

    if len(p) >= 252:
        mom = p.iloc[-21] / p.iloc[-252] - 1.0
    elif len(p) >= 126:
        mom = p.iloc[-21] / p.iloc[-126] - 1.0
    else:
        mom = pd.Series(np.nan, index=p.columns)

    if len(p) >= 126:
        mom6 = p.iloc[-21] / p.iloc[-126] - 1.0
    else:
        mom6 = pd.Series(np.nan, index=p.columns)

    r_mom = _rank_pct(mom)
    r_mom6 = _rank_pct(mom6)
    r_rev = _rank_pct(rev)
    r_lowvol = _rank_pct(-vol)
    r_lowmax = _rank_pct(-maxret)

    score = (0.40 * r_mom + 0.15 * r_mom6 + 0.20 * r_rev + 0.15 * r_lowvol + 0.10 * r_lowmax)
    score = score.replace([np.inf, -np.inf], np.nan).dropna()
    if len(score) < 10:
        return zero

    n_each = min(25, len(score) // 2)
    if n_each < 1:
        return zero

    ranked = score.sort_values(ascending=False, kind='mergesort')
    longs = ranked.index[:n_each]
    shorts = ranked.index[-n_each:]

    weight = min(0.02, 0.5 / float(n_each))
    w = pd.Series(0.0, index=u, dtype=float)
    for t in longs:
        if t in w.index:
            w.loc[t] = weight
    for t in shorts:
        if t in w.index:
            w.loc[t] = -weight

    return w.astype(float)

import numpy as np
import pandas as pd


def _zeros(universe):
    return pd.Series(0.0, index=universe, dtype=float)


def _zscore(s):
    s = s.replace([np.inf, -np.inf], np.nan)
    if s.notna().sum() < 2:
        return pd.Series(0.0, index=s.index, dtype=float)
    mu = float(s.mean())
    sd = float(s.std(ddof=0))
    if not np.isfinite(sd) or sd < 1e-12:
        return pd.Series(0.0, index=s.index, dtype=float)
    return ((s - mu) / sd).clip(-3.0, 3.0)


def generate_weights(history, universe):
    u = pd.Index(universe)
    if len(u) == 0:
        return pd.Series(dtype=float)
    empty = _zeros(u)

    adj = history.get('adjusted_close')
    if not isinstance(adj, pd.DataFrame):
        adj = history.get('close')
    if not isinstance(adj, pd.DataFrame) or adj.empty:
        frames = {}
        for t in u:
            d = history.get(t)
            if isinstance(d, pd.DataFrame) and 'adjusted_close' in d.columns:
                frames[t] = d['adjusted_close']
        if not frames:
            return empty
        adj = pd.DataFrame(frames)

    adj = adj.reindex(columns=u)
    if len(adj) < 40:
        return empty

    idx = adj.index
    last_pos = len(idx) - 1
    fridays = np.where(idx.dayofweek == 4)[0]
    if len(fridays) > 0:
        base_pos = int(fridays[-1])
    else:
        base_pos = last_pos
    if base_pos < 130:
        return empty

    start = max(0, base_pos - 259)
    p = adj.iloc[start:base_pos + 1].copy()
    if len(p) < 130:
        return empty
    p = p.ffill()

    lastp = p.iloc[-1]
    valid = lastp.notna() & (lastp.to_numpy(dtype=float) > 1.0)
    valid = pd.Series(valid, index=u)
    valid &= p.notna().sum() >= min(120, len(p))

    elig = history.get('eligible')
    if isinstance(elig, pd.DataFrame):
        e = elig.reindex(index=idx, columns=u)
        if base_pos < len(e):
            es = e.iloc[base_pos]
        else:
            es = e.iloc[-1]
        valid &= es.fillna(False).astype(bool)

    vol = history.get('volume')
    close = history.get('close')
    if isinstance(vol, pd.DataFrame):
        v = vol.reindex(index=idx, columns=u).iloc[start:base_pos + 1]
        if isinstance(close, pd.DataFrame):
            c = close.reindex(index=idx, columns=u).iloc[start:base_pos + 1]
        else:
            c = p
        if len(v) >= 5:
            vv = v.iloc[-20:]
            cc = c.iloc[-20:]
            dollar = (vv * cc).median()
            valid &= dollar.notna() & (dollar.to_numpy(dtype=float) > 1.0e6)

    if int(valid.sum()) < 10:
        return empty

    rets = p.pct_change()
    vol20 = rets.iloc[-20:].std(ddof=0)
    vol20 = vol20.replace([np.inf, -np.inf], np.nan)
    vol20 = vol20.where(vol20 > 1e-8)

    if len(p) >= 6:
        r5 = p.iloc[-1] / p.iloc[-6] - 1.0
    else:
        r5 = pd.Series(np.nan, index=u)
    if len(p) >= 22:
        r21 = p.iloc[-1] / p.iloc[-22] - 1.0
    else:
        r21 = pd.Series(np.nan, index=u)

    rev5 = -r5 / (vol20 * np.sqrt(5.0))
    rev21 = -r21 / (vol20 * np.sqrt(21.0))
    rev5 = rev5.replace([np.inf, -np.inf], np.nan)
    rev21 = rev21.replace([np.inf, -np.inf], np.nan)

    score = 0.7 * _zscore(rev5) + 0.3 * _zscore(rev21)
    score = score.replace([np.inf, -np.inf], np.nan)
    score = score.where(valid)

    cand = score.dropna()
    if len(cand) < 10:
        return empty

    beta = pd.Series(1.0, index=u, dtype=float)
    if len(rets) >= 30:
        win = rets.iloc[-120:]
        mkt = win.mean(axis=1, skipna=True)
        mkt_d = mkt - mkt.mean()
        denom = float((mkt_d * mkt_d).sum())
        if np.isfinite(denom) and denom > 1e-12:
            demean = win.sub(win.mean(axis=0), axis=1)
            cov = (demean.mul(mkt_d, axis=0)).sum() / denom
            beta = pd.Series(cov, index=u, dtype=float)
    beta = beta.replace([np.inf, -np.inf], np.nan)
    if beta.notna().any():
        beta = beta.fillna(float(beta.median()))
    else:
        beta = beta.fillna(1.0)
    beta = beta.reindex(u).fillna(1.0)

    cand_beta = beta.loc[cand.index]
    br = cand_beta.rank(method='first', pct=True)
    buckets = np.minimum((br.to_numpy(dtype=float) * 5.0).astype(int), 4)

    long_names = []
    short_names = []
    for b in range(5):
        names = cand.index[buckets == b]
        if len(names) < 2:
            continue
        ordered = cand.loc[names].sort_values(ascending=False, kind='mergesort')
        n = min(5, len(ordered) // 2)
        if n < 1:
            continue
        long_names.extend(list(ordered.index[:n]))
        short_names.extend(list(ordered.index[-n:]))

    if len(long_names) == 0 or len(long_names) != len(short_names):
        return empty

    side_count = len(long_names)
    w = min(0.02, 0.5 / float(side_count))
    out = pd.Series(0.0, index=u, dtype=float)
    for t in long_names:
        if t in out.index:
            out.loc[t] = w
    for t in short_names:
        if t in out.index:
            out.loc[t] = -w
    out = out.replace([np.inf, -np.inf], 0.0).fillna(0.0)
    return out

